 async function openPreview(batchOrId){setPreviewBusy(true);const id=typeof batchOrId==='string'?batchOrId:batchOrId.id;const batch=typeof batchOrId==='string'?batches.find(x=>x.id===id):batchOrId;const{data,error}=await supabase.from('hrc_payroll_salary_change_items').select('id,employee_id,old_salary,new_salary,hr_employees:hrc_hr_employees(employee_no,first_name,last_name,employment_type,departments:hrc_departments(name),hr_positions:hrc_hr_positions(title))').eq('tenant_id',tenant.id).eq('batch_id',id).order('old_salary');setPreviewBusy(false);if(error)return setMsg(error.message);setPreviewBatch(batch||{id});setPreviewItems(data||[]);setReversalReason('');setMsg(`Preview loaded for ${(data||[]).length} employee${data?.length===1?'':'s'}. Verify the details before approval.`);setTimeout(()=>document.getElementById('salary-adjustment-preview')?.scrollIntoView({behavior:'smooth',block:'start'}),80)}
 async function preview(){if(scope!=='all'&&!scopeValue)return setMsg('Select the employee/category to receive the salary adjustment.');if(!value||Number(value)<=0)return setMsg('Enter a salary adjustment value greater than zero.');setPreviewBusy(true);const{data,error}=await supabase.rpc('payroll_create_scoped_salary_batch',{p_tenant:tenant.id,p_scope:scope,p_scope_value:scope==='all'?null:scopeValue,p_mode:mode,p_value:Number(value),p_effective:date,p_reason:reason});setPreviewBusy(false);if(error)return setMsg(error.message);await load();const batch={id:data.batch_id,batch_no:'New draft',scope_label:data.scope_label,scope_type:scope,change_mode:mode,value:Number(value),effective_date:date,reason,status:'draft'};await openPreview(batch)}
