 <section className="panel"><h3>{audit?'Audit records':'Approval history'}</h3><Table headers={audit?['When','Module','Action','Entity','Reference','User / Actor']:['When','Workflow','Reference','Status','Submitted by','Approved by']} rows={audit?filtered.map(x=>[x.created_at?new Date(x.created_at).toLocaleString():'—',x.module||x.domain||'—',x.action||'—',x.entity_type||'—',x.entity_reference||'—',x.actor_label||x.actor_id||'—']):filtered.map(x=>[x.created_at?new Date(x.created_at).toLocaleString():'—',x.workflow_type||'—',x.reference||'—',<span className={`status ${x.status}`}>{x.status}</span>,x.submitted_label||x.submitted_by||'—',x.approved_label||x.approved_by||'—'])}/></section>
