function Table({headers,rows}){return <div className="tableWrap"><table><thead><tr>{headers.map(h=><th key={h}>{h}</th>)}</tr></thead><tbody>{rows.length?rows.map((r,i)=><tr key={i}>{r.map((v,j)=><td key={j}>{v}</td>)}</tr>):<tr><td colSpan={headers.length} className="muted">No records yet.</td></tr>}</tbody></table></div>}
function Metric({title,value}){return <div className="card"><span>{title}</span><strong>{value}</strong></div>}

