 async function saveManual(e){e.preventDefault();if(!manual.employee_id)return setMsg('Select an employee.');if(!manual.reason.trim())return setMsg('Reason is required for manual attendance entry or correction.');const ts=(t)=>t?`${manual.work_date}T${t}:00+00:00`:null;const{error}=await supabase.rpc('hr_admin_upsert_attendance',{p_tenant:tenant.id,p_employee:manual.employee_id,p_work_date:manual.work_date,p_check_in:['absent','on_leave','holiday','off_day'].includes(manual.status)?null:ts(manual.check_in),p_check_out:['absent','on_leave','holiday','off_day'].includes(manual.status)?null:ts(manual.check_out),p_status:manual.status,p_site:manual.site_id||null,p_reason:manual.reason,p_capture_method:'manual'});setMsg(error?.message||'Attendance record saved with audit trail.');if(!error){setManual(x=>({...x,reason:''}));await Promise.all([load(),loadAdmin()])}}
