 function locate(){if(!window.isSecureContext&&location.hostname!=='localhost')return setMsg('GPS capture is blocked because this page is using HTTP. Use HTTPS for phone/LAN GPS, or enter coordinates manually for site setup.');if(!navigator.geolocation)return setMsg('Location is unavailable in this browser.');navigator.geolocation.getCurrentPosition(p=>{setF(x=>({...x,latitude:p.coords.latitude.toFixed(7),longitude:p.coords.longitude.toFixed(7)}));setMsg(`Location captured ✓ Accuracy about ±${Math.round(p.coords.accuracy)} m.`)},e=>setMsg(`Location permission failed: ${e.message}`),{enableHighAccuracy:true,timeout:15000,maximumAge:0})}
