  const knownNativeCode=code==='GEN-ATTEND'||code==='GEN-LEAVE'||code==='GEN-TRAINING';
  const knownNativeName=(name==='attendance'||name.includes('attendance & punctuality'))&&(src.includes('attendance')||src==='native'||src.includes('hrpayrollcore'));
