  if(!m)return {include:false,reason:'Measure definition not found'};
  if(isNativeSystemMeasure(m))return {include:false,reason:'Native HRPayrollCore source'};
  if(isHumanObservationMeasure(m))return {include:false,reason:'Supervisor / behavioural observation'};
