   const activeReviews=reviews.filter(r=>r.employee_id===emp.id&&r.plan_status==='activated'),review=activeReviews[0];
   let items=review?planItems.filter(x=>x.review_id===review.id):[];
   let origin='Activated employee plan',resolvedTemplate=null;
   if(!items.length){resolvedTemplate=matchingTemplate(emp);if(resolvedTemplate){items=templateItems.filter(x=>x.template_id===resolvedTemplate.id);origin=`Auto-matched template: ${resolvedTemplate.name}`}}
