  if(!measures.length){const msg=`No ${gen.frequency} external/manual collection fields remain after source filtering. Nothing was downloaded because all selected-plan measures are already system/supervisor sourced.`;setStatus(msg);notify(msg);return}

  const token=`HRPC-${Date.now().toString(36).toUpperCase()}`;
  const cols=['HRPC_TEMPLATE_TOKEN','EMPLOYEE_ID','EMPLOYEE_NO','EMPLOYEE_NAME','PLAN_REVIEW_ID','OBSERVATION_DATE','PERIOD',...measures.map(x=>x.code)];
